import Foundation
import XCTest
@testable import IntentgateBasicAuth

/// Cross-language test vectors generated by the TypeScript reference (spec/test-vectors.json).
final class VectorsTests: XCTestCase {
    private var vectors: JSONValue!

    override func setUpWithError() throws {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("spec/test-vectors.json")
        vectors = try JSONValue.parse(Data(contentsOf: url))
    }

    func testJcsMatchesReference() throws {
        for c in vectors["jcs"]!.arrayValue! {
            XCTAssertEqual(try Jcs.canonicalize(c["input"]!), c["canonical"]!.stringValue!)
        }
    }

    func testChallengeMatchesReference() throws {
        let v = vectors["challenge"]!
        let event = try CheckInEvent(json: v["event"]!)
        XCTAssertEqual(try event.canonicalJSON(), v["event_canonical"]!.stringValue!)
        XCTAssertEqual(try Challenge.computeBase64Url(event: event), v["challenge_b64url"]!.stringValue!)
    }

    func testRejectsWhatTheReferenceRejects() {
        XCTAssertThrowsError(try Jcs.canonicalize(["a": .double(1.5)]))
        XCTAssertThrowsError(try Jcs.canonicalize(.int(9_007_199_254_740_992)))
        XCTAssertThrowsError(try JSONValue.parse(#"{"a":1.5}"#).objectValue.map { try Jcs.canonicalize(.object($0)) })
        XCTAssertNil(Base64Url.decode("a+b/"))
    }
}
